-- Create "automations" table
CREATE TABLE "public"."automations" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" character varying NOT NULL,
  "status" character varying NOT NULL DEFAULT 'draft',
  "trigger_event" character varying NOT NULL,
  "definition" character varying NOT NULL DEFAULT '[]',
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "automations_workspaces_automations" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "automation_workspace_id" to table: "automations"
CREATE INDEX "automation_workspace_id" ON "public"."automations" ("workspace_id");
-- Create index "automation_workspace_id_status_trigger_event" to table: "automations"
CREATE INDEX "automation_workspace_id_status_trigger_event" ON "public"."automations" ("workspace_id", "status", "trigger_event");
-- Create "automation_runs" table
CREATE TABLE "public"."automation_runs" (
  "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "contact_id" bigint NOT NULL,
  "status" character varying NOT NULL DEFAULT 'active',
  "current_step" bigint NOT NULL DEFAULT 0,
  "resume_at" timestamptz NULL,
  "created_at" timestamptz NOT NULL,
  "updated_at" timestamptz NOT NULL,
  "automation_id" bigint NOT NULL,
  "workspace_id" bigint NOT NULL,
  PRIMARY KEY ("id"),
  CONSTRAINT "automation_runs_automations_runs" FOREIGN KEY ("automation_id") REFERENCES "public"."automations" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION,
  CONSTRAINT "automation_runs_workspaces_automation_runs" FOREIGN KEY ("workspace_id") REFERENCES "public"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION
);
-- Create index "automation_runs_automation_id_contact_id" to table: "automation_runs"
CREATE UNIQUE INDEX "automation_runs_automation_id_contact_id" ON "public"."automation_runs" ("automation_id", "contact_id");
